import{_ as a,o as r,c as t,ae as n}from"./chunks/framework.Dn6zxbF8.js";const h=JSON.parse('{"title":"Vinaykumar V A","titleTemplate":false,"description":"","frontmatter":{"layout":"home","title":"Vinaykumar V A","titleTemplate":false,"hero":{"name":"Vinaykumar V A","text":"Backend Engineer · Go & Kubernetes","tagline":"4.5+ years building scalable backend services and cloud-native apps in Golang.","actions":[{"theme":"brand","text":"View Work","link":"/#work"},{"theme":"alt","text":"Read the Blog","link":"/blog/"},{"theme":"alt","text":"GitHub","link":"https://github.com/vinaycharlie01"}]}},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),o={name:"index.md"};function i(s,e,l,c,d,g){return r(),t("div",null,[...e[0]||(e[0]=[n('<h2 id="about" tabindex="-1">About <a class="header-anchor" href="#about" aria-label="Permalink to &quot;About&quot;">​</a></h2><p>Backend Engineer with 4.5+ years of experience developing scalable backend services and cloud-native applications using Golang. Experienced in microservices, distributed systems, REST APIs, concurrency, event-driven architecture, and Kubernetes automation. Hands-on expertise in PostgreSQL, Kafka, Redis, Docker, Helm, CI/CD, and OpenTelemetry-based observability across AWS, GCP, and IBM Cloud.</p><h2 id="skills" tabindex="-1">Skills <a class="header-anchor" href="#skills" aria-label="Permalink to &quot;Skills&quot;">​</a></h2><ul><li><strong>Languages &amp; Frameworks:</strong> Golang (primary), Gin, concurrency patterns, gRPC, ProtoBuf, RESTful APIs</li><li><strong>Containers &amp; Orchestration:</strong> Docker, Kubernetes, K3s, Helm, Operators</li><li><strong>Messaging &amp; Databases:</strong> PostgreSQL, MySQL, MongoDB, Cassandra, ClickHouse, Redis, Kafka</li><li><strong>Cloud &amp; DevOps:</strong> AWS, GCP, IBM Cloud, Helm, Kubernetes Operators, CI/CD</li><li><strong>Observability &amp; Debugging:</strong> Instana, OpenTelemetry, Prometheus, Grafana, Elasticsearch/Kibana, Delve</li><li><strong>CI/CD &amp; Version Control:</strong> Concourse, Git, GitHub, Jenkins</li><li><strong>Tools &amp; OS:</strong> Linux, macOS, VS Code, Zed, Tilt, Telepresence, JIRA</li></ul><h2 id="work" tabindex="-1">Work <a class="header-anchor" href="#work" aria-label="Permalink to &quot;Work&quot;">​</a></h2><h3 id="software-engineer-—-pinelabs" tabindex="-1">Software Engineer — PineLabs <a class="header-anchor" href="#software-engineer-—-pinelabs" aria-label="Permalink to &quot;Software Engineer — PineLabs&quot;">​</a></h3><p><strong>May 2026 – Present · Bengaluru, India</strong></p><p><strong>Stack:</strong> Golang, Microservices, REST API, Kubernetes, Helm, Docker, GCP, Concourse CI/CD, Linux</p><ul><li>Built the QR-code scanning workflow in Golang using clean architecture: business logic, database operations, request validation, and error handling.</li><li>Drove the full migration of .NET modules to Golang, including architecture design, code improvements, scalability, and Kubernetes deployment.</li><li>Built a queue-based notification framework integrating email, SMS, and WhatsApp delivery services for decoupled, scalable processing.</li><li>Designed a reusable caching framework to reduce redundant database queries and improve backend performance and scalability.</li><li>Implemented OTP login workflows — send, resend, and verify — through service integrations.</li><li>Delivered business and admin REST APIs with validation, business rules, database consistency checks, and standardized error handling.</li><li>Integrated OpenTelemetry metrics, traces, and logs for service visibility, performance analysis, and production troubleshooting.</li><li>Used Postman and MCP tooling to validate API workflows; built read-only PostgreSQL and Microsoft SQL Server MCP tools for AI-assisted schema exploration, query analysis, and database troubleshooting.</li><li>Collaborated with DevOps and monitoring teams on Kubernetes deployments, observability configuration, and environment troubleshooting.</li></ul><h3 id="software-developer-—-ibm-instana" tabindex="-1">Software Developer — IBM | Instana <a class="header-anchor" href="#software-developer-—-ibm-instana" aria-label="Permalink to &quot;Software Developer — IBM | Instana&quot;">​</a></h3><p><strong>Nov 2024 – May 2026 · Kochi, India</strong></p><p><strong>Stack:</strong> Golang, Kubernetes, Operators, Helm, Docker, GCP, Concourse CI/CD, Linux</p><ul><li>Developed and maintained <code>stanctl</code>, a self-hosted CLI in Golang to automate Instana deployment.</li><li>Designed, developed, and maintained a Kubernetes Operator in Golang to automate the deployment and lifecycle management of Instana components.</li><li>Added CLI automation for creating VPCs on IBM Cloud, provisioning Kubernetes clusters, and deploying Instana agents end-to-end.</li><li>Handled major agent upgrades smoothly and added flags to control Helm chart values dynamically.</li><li>Enhanced Kubernetes component support, including CoreDNS and Metrics Server automation on K3s using Go and YAML templates.</li><li>Designed k8s-diagnostics using Go and client-go for cluster health analysis.</li></ul><h3 id="software-engineer-—-msys-technology-client-hpe" tabindex="-1">Software Engineer — MSYS Technology (Client: HPE) <a class="header-anchor" href="#software-engineer-—-msys-technology-client-hpe" aria-label="Permalink to &quot;Software Engineer — MSYS Technology (Client: HPE)&quot;">​</a></h3><p><strong>April 2022 – Nov 2024 · Bangalore, India</strong></p><p><strong>Stack:</strong> Go, MongoDB, PostgreSQL, Microservices, Kafka, REST API, Elasticsearch, Docker, Jenkins, Consul, Redis</p><ul><li>Built a wellness application for HPE clients that processed storage-array input events under an event-driven architecture.</li><li>Wrote Go microservices with pointers, goroutines, channels, concurrency patterns, and unit tests; generated Salesforce tickets for HPE support engineers to resolve storage-array issues.</li><li>Developed plugins via shared object files and used Kafka for real-time data processing and message streaming.</li><li>Containerized services with Docker, automated delivery with Jenkins CI/CD, and used Elasticsearch for visualization, queries, and log management.</li></ul><h2 id="projects" tabindex="-1">Projects <a class="header-anchor" href="#projects" aria-label="Permalink to &quot;Projects&quot;">​</a></h2><p>Open-source cloud-native tools I build and maintain under <a href="https://nirantarasi.github.io/" target="_blank" rel="noreferrer">Nirantara</a> — full docs at <a href="https://nirantarasi.github.io/" target="_blank" rel="noreferrer">nirantarasi.github.io</a>.</p><h3 id="k3sctl" tabindex="-1">k3sctl <a class="header-anchor" href="#k3sctl" aria-label="Permalink to &quot;k3sctl&quot;">​</a></h3><p>Install, upgrade, back up, and reset K3s clusters from one declarative YAML file, entirely over SSH.</p><p><strong>Docs:</strong> <a href="https://nirantarasi.github.io/docs/k3sctl/" target="_blank" rel="noreferrer">nirantarasi.github.io/docs/k3sctl</a> · <strong>Stack:</strong> Go, Kubernetes, K3s, SSH</p><h3 id="mssql-mcp-go" tabindex="-1">mssql-mcp-go <a class="header-anchor" href="#mssql-mcp-go" aria-label="Permalink to &quot;mssql-mcp-go&quot;">​</a></h3><p>A read-only Model Context Protocol server that gives AI assistants structured access to Microsoft SQL Server.</p><p><strong>Docs:</strong> <a href="https://nirantarasi.github.io/docs/mssql-mcp-go/" target="_blank" rel="noreferrer">nirantarasi.github.io/docs/mssql-mcp-go</a> · <strong>Stack:</strong> Go, SQL Server, MCP</p><h3 id="postgres-mcp-go" tabindex="-1">postgres-mcp-go <a class="header-anchor" href="#postgres-mcp-go" aria-label="Permalink to &quot;postgres-mcp-go&quot;">​</a></h3><p>The same read-only MCP toolset for PostgreSQL — schema, profiling, performance, security, and migration analysis.</p><p><strong>Docs:</strong> <a href="https://nirantarasi.github.io/docs/postgres-mcp-go/" target="_blank" rel="noreferrer">nirantarasi.github.io/docs/postgres-mcp-go</a> · <strong>Stack:</strong> Go, PostgreSQL, MCP</p><h3 id="omniroute-operator" tabindex="-1">omniroute-operator <a class="header-anchor" href="#omniroute-operator" aria-label="Permalink to &quot;omniroute-operator&quot;">​</a></h3><p>A Kubebuilder operator that reconciles Deployments, Services, PVCs, and Ingresses for OmniRoute from a single custom resource.</p><p><strong>Docs:</strong> <a href="https://nirantarasi.github.io/docs/omniroute-operator/" target="_blank" rel="noreferrer">nirantarasi.github.io/docs/omniroute-operator</a> · <strong>Stack:</strong> Go, Kubernetes, Kubebuilder</p><h3 id="k0s-cluster-shared-framework-k0s-cluster-shared" tabindex="-1">K0s Cluster Shared Framework (k0s-cluster-shared) <a class="header-anchor" href="#k0s-cluster-shared-framework-k0s-cluster-shared" aria-label="Permalink to &quot;K0s Cluster Shared Framework (k0s-cluster-shared)&quot;">​</a></h3><p><strong>Golang | Kubernetes | Hexagonal Architecture | k0s | k0sctl</strong></p><ul><li>Designed and implemented a hexagonal (ports &amp; adapters) cluster automation library in Go.</li><li>Abstracted Kubernetes cluster lifecycle operations — Apply, Reset, GetStatus, and GetKubeconfig — behind clean port interfaces.</li><li>Built a pluggable adapter over the k0sctl action layer to manage control-plane and worker nodes programmatically.</li><li>Implemented structured logging with <code>slog</code> and followed SOLID principles and dependency inversion to decouple business logic from orchestration tools.</li></ul><h3 id="golang-code-generator" tabindex="-1">Golang Code Generator <a class="header-anchor" href="#golang-code-generator" aria-label="Permalink to &quot;Golang Code Generator&quot;">​</a></h3><p>Generate Go structs from JSON.</p><p><strong>Stack:</strong> Go, JSON, Mux</p><h3 id="image-message-queuing-system" tabindex="-1">Image Message Queuing System <a class="header-anchor" href="#image-message-queuing-system" aria-label="Permalink to &quot;Image Message Queuing System&quot;">​</a></h3><p>API → database → download/compress product images.</p><p><strong>Stack:</strong> Golang, MongoDB, Kafka</p><h3 id="in-memory-data-aggregation-api" tabindex="-1">In-Memory Data Aggregation API <a class="header-anchor" href="#in-memory-data-aggregation-api" aria-label="Permalink to &quot;In-Memory Data Aggregation API&quot;">​</a></h3><p>High-throughput ad-network aggregation for billions of requests/day with thread-safe DAU aggregation, Kafka + a dead letter queue, Prometheus/Grafana, and graceful shutdown.</p><p><strong>Stack:</strong> Go, MongoDB, Docker, Kafka, Prometheus, Grafana</p><h2 id="achievements" tabindex="-1">Achievements <a class="header-anchor" href="#achievements" aria-label="Permalink to &quot;Achievements&quot;">​</a></h2><ul><li><strong>Google Cloud Agentic AI Day 2025</strong> — shortlisted among 700+ teams out of 50,000+ submissions; built an AI solution focused on automation and cloud-native deployment.</li><li><strong>Cardano Blockchain Hackathon</strong> — developed and deployed an AI Agent on the Musami Network using Go, integrating backend services with blockchain smart contracts.</li></ul><h2 id="education" tabindex="-1">Education <a class="header-anchor" href="#education" aria-label="Permalink to &quot;Education&quot;">​</a></h2><p><strong>AMC Engineering College</strong> — B.E., Electrical &amp; Electronics Engineering, 2021, Bangalore, India.</p><h2 id="find-me" tabindex="-1">Find Me <a class="header-anchor" href="#find-me" aria-label="Permalink to &quot;Find Me&quot;">​</a></h2><ul><li><strong>GitHub:</strong> <a href="https://www.github.com/vinaycharlie01" target="_blank" rel="noreferrer">github.com/vinaycharlie01</a></li><li><strong>LinkedIn:</strong> <a href="https://www.linkedin.com/in/vinaycharlie01" target="_blank" rel="noreferrer">linkedin.com/in/vinaycharlie01</a></li><li><strong>X (Twitter):</strong> <a href="https://x.com/VinayKshatriy12" target="_blank" rel="noreferrer">x.com/VinayKshatriy12</a></li><li><strong>Medium:</strong> <a href="https://vinaycharlie07.medium.com/" target="_blank" rel="noreferrer">vinaycharlie07.medium.com</a></li><li><strong>Email:</strong> <a href="mailto:vinikshatriyas@gmail.com" target="_blank" rel="noreferrer">vinikshatriyas@gmail.com</a></li><li><strong>Phone:</strong> <a href="tel:+919380862951" target="_blank" rel="noreferrer">(+91) 9380862951</a></li><li><strong>Portfolio:</strong> <a href="https://vinaycharlie01.github.io" target="_blank" rel="noreferrer">vinaycharlie01.github.io</a></li><li><strong>Location:</strong> Bengaluru, India</li></ul>',49)])])}const m=a(o,[["render",i]]);export{h as __pageData,m as default};
